function liveRedemptions(a) {
    return a.redemptions.filter((r) => !r.voidedAt);
}
function itemOf(db, comp) {
    const item = db.shopItems.find((i) => i.id === comp.itemId);
    if (!item) {
        return {
            itemId: comp.itemId,
            name: comp.label,
            kind: comp.kind,
            storeId: comp.storeId,
            value: comp.value ?? 0,
            basePrice: comp.basePrice ?? 0,
            stock: comp.stock,
            validDays: comp.validDays,
            active: true,
        };
    }
    return {
        itemId: item.id,
        name: item.name,
        kind: item.kind,
        storeId: item.storeId,
        value: comp.value ?? item.value,
        basePrice: comp.basePrice ?? item.basePrice,
        stock: item.stock,
        validDays: item.validDays,
        holidays: item.holidays,
        active: item.active,
    };
}
function holidayAllowed(ri, holidayName) {
    return !ri.holidays?.length || ri.holidays.includes(holidayName);
}
function itemRemaining(db, itemId) {
    const item = db.shopItems.find((i) => i.id === itemId);
    if (!item || item.stock === undefined)
        return null;
    let used = 0;
    for (const a of db.shopAssignments) {
        const p = db.shopProducts.find((x) => x.id === a.productId);
        if (!p)
            continue;
        for (const r of liveRedemptions(a)) {
            const c = p.components.find((x) => x.id === r.componentId);
            if (c?.itemId === itemId)
                used++;
        }
    }
    return Math.max(0, item.stock - used);
}
function maxDiscountPct(criterionIds, criteria) {
    let pct = 0;
    for (const id of criterionIds) {
        const c = criteria.find((x) => x.id === id);
        if (c && Number.isFinite(c.discountPct) && c.discountPct > pct)
            pct = c.discountPct;
    }
    return Math.min(100, Math.max(0, pct));
}
function componentRemaining(componentId, productId, assignments, stock) {
    if (stock === undefined)
        return null;
    let used = 0;
    for (const a of assignments) {
        if (a.productId !== productId)
            continue;
        for (const r of liveRedemptions(a))
            if (r.componentId === componentId)
                used++;
    }
    return Math.max(0, stock - used);
}
